import type { APIRequestContext } from '@playwright/test';

export { CANNED_FALLBACK, CATEGORIES } from '../../api/src/lib/categories';

export const CHECKIN_Q = 'What time is check-in?';
export const HELIPAD_Q = 'Is there a helipad on the roof?';

/** The sample PDF generated by `pnpm sample:pdf`. */
export const SAMPLE_PDF = new URL('../../../docs/sample/cincinnati-hotel.pdf', import.meta.url);
export const SAMPLE_QUESTIONS = new URL('../../../docs/sample/questions.json', import.meta.url);

/** True when the API runs with N8N_MOCK=1 (health reports `n8n: "mock"`). */
export async function isMockMode(request: APIRequestContext): Promise<boolean> {
  const res = await request.get('/api/health');
  const body = (await res.json()) as { n8n: 'up' | 'down' | 'mock' };
  return body.n8n === 'mock';
}

/** n8n webhook base for the `real` project; the editor port is published by compose.override.yml. */
export const N8N_URL = process.env.E2E_N8N_URL ?? 'http://localhost:5678';

